SELECT COUNT(*)
FROM QUERY_REQUEST Q
WHERE Q.REQUEST_ID = #{requestId}
  AND (
      Q.DRAFTER_ID = #{actorId}
      OR EXISTS (
          SELECT 1
          FROM APPROVAL A
          WHERE A.REQUEST_ID = Q.REQUEST_ID
            AND A.APPROVER_ID = #{actorId}
      )
      OR EXISTS (
          SELECT 1
          FROM APPROVAL A
          JOIN USERS ACTOR ON ACTOR.USER_ID = #{actorId}
          WHERE A.REQUEST_ID = Q.REQUEST_ID
            AND A.TARGET_TYPE = 'DEPARTMENT'
            AND A.APPROVER_DEPT_ID = ACTOR.DEPT_ID
            AND ACTOR.ENABLED = 'Y'
      )
  )

SELECT I.QUERY_ID, I.QUERY_ORDER, I.QUERY_TITLE, I.SQL_TEXT, I.AUTHORING_TYPE, I.VALIDATION_STATUS, I.ITEM_CLASS FROM QUERY_ITEM I JOIN QUERY_REQUEST R ON R.REQUEST_ID = I.REQUEST_ID WHERE I.REQUEST_ID = #{requestId} AND R.REQUEST_TYPE = 'SELECT' AND EXISTS ( SELECT 1 FROM APPROVAL A JOIN USERS U ON U.USER_ID = #{approverId} WHERE A.REQUEST_ID = I.REQUEST_ID
)
UNION ALL
SELECT V.QUERY_ID, V.QUERY_ORDER, V.SQL_TITLE AS QUERY_TITLE, V.SQL_CONTENT AS SQL_TEXT, NULL AS AUTHORING_TYPE, NULL AS VALIDATION_STATUS, NULL AS ITEM_CLASS FROM DB_CHANGE_SQL V JOIN QUERY_REQUEST R ON R.REQUEST_ID = V.REQUEST_ID WHERE V.REQUEST_ID = #{requestId} AND R.REQUEST_TYPE IN ('CREATE', 'INSERT', 'UPDATE', 'DELETE') AND EXISTS ( SELECT 1 FROM APPROVAL A JOIN USERS U ON U.USER_ID = #{approverId} WHERE A.REQUEST_ID = V.REQUEST_ID
)
ORDER BY QUERY_ORDER, QUERY_ID

SELECT U.USER_ID, U.DEPT_ID, U.USER_NAME, D.DEPT_NAME, P.POSITION_NAME FROM USERS U JOIN DEPARTMENT D ON D.DEPT_ID = U.DEPT_ID JOIN POSITION P ON P.POSITION_ID = U.POSITION_ID WHERE U.ENABLED = 'Y' AND U.USER_ID <> #{excludedUserId}
AND ( LOWER(U.USER_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(D.DEPT_NAME) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY D.DEPT_NAME ASC, P.POSITION_LEVEL DESC NULLS LAST, U.USER_NAME ASC, U.USER_ID ASC

SELECT D.DEPT_ID, D.DEPT_NAME, COUNT(U.USER_ID) AS ELIGIBLE_USER_COUNT FROM DEPARTMENT D LEFT JOIN USERS U ON U.DEPT_ID = D.DEPT_ID AND U.ENABLED = 'Y' AND U.USER_ID <> #{excludedUserId}
LOWER(D.DEPT_NAME) LIKE '%' || LOWER(#{keyword}) || '%'
GROUP BY D.DEPT_ID, D.DEPT_NAME ORDER BY D.DEPT_NAME, D.DEPT_ID

