UPDATE APPROVAL A
SET STATUS = 'APPROVED',
    APPROVER_ID = #{approverId},
    DECIDED_AT = SYSTIMESTAMP
WHERE A.APPROVAL_ID = #{approvalId}
  AND EXISTS (
      SELECT 1
      FROM USERS U
      WHERE U.USER_ID = #{approverId}

  )
